  if (productsRes.status !== 200) {
    throw new Error(`products failed: ${productsRes.status} ${productsRes.body}`);
  }

  // 3 - POST /cart
  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: "sku-1" }),
    { headers: { "Content-Type": "application/json", "X-CSRF-Token": csrf } }
