  vus: 1,
  iterations: 2,
};

export default function () {
  const rawBase = __ENV.BASE_URL;
  if (!rawBase) {
    throw new Error('BASE_URL not set');
  }
  const baseUrl = rawBase.endsWith('/') ? rawBase.slice(0, -1) : rawBase;

  // 1. POST /login
  const loginRes = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: "bench", password: "bench" }),
    { headers: { "Content-Type": "application/json" } }
  );
  check(loginRes, { "login 200": (r) => r.status === 200 });
  if (loginRes.status !== 200) {
    throw new Error(`login failed: ${loginRes.status} ${loginRes.body}`);
  }
  let csrf;
  try {
    csrf = loginRes.json("csrf");
    if (!csrf) {
      csrf = JSON.parse(loginRes.body).csrf;
    }
  } catch (e) {
    csrf = JSON.parse(loginRes.body).csrf;
  }
  if (!csrf) {
    throw new Error("csrf not found in login response");
  }

  // 2. GET /products
  const prodRes = http.get(`${baseUrl}/products`);
  check(prodRes, { "products 200": (r) => r.status === 200 });
  if (prodRes.status !== 200) {
    throw new Error(`products failed: ${prodRes.status} ${prodRes.body}`);
  }

  // 3. POST /cart
  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: "sku-1" }),
    { headers: { "Content-Type": "application/json", "X-CSRF-Token": csrf } }
  );
  check(cartRes, { "cart 200": (r) => r.status === 200 });
  if (cartRes.status !== 200) {
    throw new Error(`cart failed: ${cartRes.status} ${cartRes.body}`);
  }

  // 4. POST /checkout
