    `${baseUrl}/checkout`,
    JSON.stringify({}),
    { headers: { "Content-Type": "application/json", "X-CSRF-Token": csrf } }
  );
  check(checkoutRes, { "checkout 200": (r) => r.status === 200 });
  if (checkoutRes.status !== 200) {
    throw new Error(`checkout failed: ${checkoutRes.status} ${checkoutRes.body}`);
  }
}
